import com.example.payment.domain.shared.Money;
import java.util.Objects;

public final class Order {

    private final OrderId id;
    private final CustomerId customerId;
    private final Money total;
    private OrderStatus status;

    private Order(OrderId id, CustomerId customerId, Money total, OrderStatus status) {
        this.id = Objects.requireNonNull(id);
        this.customerId = Objects.requireNonNull(customerId);
        this.total = Objects.requireNonNull(total);
        this.status = Objects.requireNonNull(status);
    }

    public static Order place(OrderId id, CustomerId customerId, Money total) {
        return new Order(id, customerId, total, OrderStatus.PENDING);
    }

    public boolean isOwnedBy(CustomerId caller) {
        return customerId.equals(caller);
    }

    /** A foreign order is reported as missing so its existence is not disclosed. */
    public void cancel(CustomerId caller) {
        if (!isOwnedBy(caller)) throw new OrderNotFoundException(id);
        if (status != OrderStatus.PENDING) throw new OrderNotCancellableException(id, status);
        status = OrderStatus.CANCELLED;
    }

    public OrderId id() { return id; }

    public CustomerId customerId() { return customerId; }

    public Money total() { return total; }

    public OrderStatus status() { return status; }
}
