package com.example.payment.application.order;

import com.example.payment.domain.order.CustomerId;
import com.example.payment.domain.order.Order;
import com.example.payment.domain.order.OrderId;
import com.example.payment.domain.order.OrderNotFoundException;
import com.example.payment.domain.order.OrderRepository;

public final class GetOrder {

    private final OrderRepository orders;

    public GetOrder(OrderRepository orders) {
        this.orders = orders;
    }

    public OrderViewModel execute(OrderId id, CustomerId caller) {
        Order order = orders.findById(id)
                .filter(found -> found.isOwnedBy(caller))
                .orElseThrow(() -> new OrderNotFoundException(id));
        return new OrderViewModel(
                order.id().value(),
                order.customerId().value(),
                order.total().amount(),
                order.total().currency(),
                order.status().name());
    }
}
