package com.example.payment.application.order;

import com.example.payment.domain.order.CustomerId;
import com.example.payment.domain.order.Order;
import com.example.payment.domain.order.OrderId;
import com.example.payment.domain.order.OrderNotFoundException;
import com.example.payment.domain.order.OrderRepository;

public final class CancelOrder {

    private final OrderRepository orders;

    public CancelOrder(OrderRepository orders) {
        this.orders = orders;
    }

    public void execute(OrderId id, CustomerId caller) {
        Order order = orders.findById(id).orElseThrow(() -> new OrderNotFoundException(id));
        order.cancel(caller);
        orders.save(order);
    }
}
