package com.example.payment.app;

import com.example.payment.application.order.CancelOrder;
import com.example.payment.application.order.GetOrder;
import com.example.payment.application.order.OrderViewModel;
import com.example.payment.domain.order.CustomerId;
import com.example.payment.domain.order.OrderId;
import com.example.payment.domain.order.OrderNotCancellableException;
import com.example.payment.domain.order.OrderNotFoundException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RestController;

@RestController
class OrderController {

    private final GetOrder getOrder;
    private final CancelOrder cancelOrder;

    OrderController(GetOrder getOrder, CancelOrder cancelOrder) {
        this.getOrder = getOrder;
        this.cancelOrder = cancelOrder;
    }

    @GetMapping("/orders/{id}")
    OrderViewModel get(@PathVariable String id, @RequestHeader("X-Customer-Id") String customerId) {
        return getOrder.execute(new OrderId(id), new CustomerId(customerId));
    }

    @PostMapping("/orders/{id}/cancel")
    ResponseEntity<Void> cancel(@PathVariable String id, @RequestHeader("X-Customer-Id") String customerId) {
        cancelOrder.execute(new OrderId(id), new CustomerId(customerId));
        return ResponseEntity.noContent().build();
    }

    @ExceptionHandler(OrderNotFoundException.class)
    ResponseEntity<String> notFound(OrderNotFoundException e) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND).body(e.getMessage());
    }

    @ExceptionHandler(OrderNotCancellableException.class)
    ResponseEntity<String> conflict(OrderNotCancellableException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(e.getMessage());
    }

    @ExceptionHandler(IllegalArgumentException.class)
    ResponseEntity<String> badRequest(IllegalArgumentException e) {
        return ResponseEntity.badRequest().body(e.getMessage());
    }
}
