package com.example.payment.app;

import com.example.payment.application.order.CancelOrder;
import com.example.payment.application.order.GetOrder;
import com.example.payment.domain.order.OrderRepository;
import com.example.payment.infrastructure.order.InMemoryOrderRepository;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
class OrderConfiguration {

    @Bean
    OrderRepository orderRepository() {
        return new InMemoryOrderRepository();
    }

    @Bean
    GetOrder getOrder(OrderRepository orders) {
        return new GetOrder(orders);
    }

    @Bean
    CancelOrder cancelOrder(OrderRepository orders) {
        return new CancelOrder(orders);
    }
}
